#include <unordered_set>
using namespace std;
int main(){
 ios::sync_with_stdio(false); cin.tie(nullptr);
 int P,Q;cin>>P>>Q;
 struct Node{array<int,26> go{};int fail=0;bool hit=false;};vector<Node> tr(1);
 for(int k=0;k<P;++k){string s;cin>>s;int v=0;for(char c:s){int x=c-'a';if(!tr[v].go[x]){int u=int(tr.size());tr[v].go[x]=u;tr.emplace_back();}v=tr[v].go[x];}tr[v].hit=true;}
 queue<int> qu;for(int x=0;x<26;++x)if(tr[0].go[x])qu.push(tr[0].go[x]);
 while(!qu.empty()){int v=qu.front();qu.pop();tr[v].hit=tr[v].hit||tr[tr[v].fail].hit;
 for(int x=0;x<26;++x){int u=tr[v].go[x];if(u){tr[u].fail=tr[tr[v].fail].go[x];qu.push(u);}else tr[v].go[x]=tr[tr[v].fail].go[x];}}
 while(Q--){string s;cin>>s;int v=0;bool hit=false;for(char c:s){v=tr[v].go[c-'a'];hit=hit||tr[v].hit;}cout<<(hit?"YES":"NO")<<'\n';}
}

